se_verdict(raw: str) -> float | None:\\n    \\\"\\\"\\\"Extract pairwise verdict. Returns 1.0/0.0/0.5/None.\\\"\\\"\\\"\\n    match = re.search(r\\\"\\\\[\\\\[([ABC])\\\\]\\\\]\\\", raw)\\n    if not match:\\n        return None\\n    v = match.group(1)\\n    if v == \\\"A\\\":\\n        return 1.0\\n    elif v == \\\"B\\\":\\n        return 0.0\\n    return 0.5\\n\\n\\ndef _parse_pointwise_score(raw: str) -> float | None:\\n    \\\"\\\"\\\"Extract pointwise rating [[N]] where N in 1-10. Returns float or None.\\\"\\\"\\\"\\n    match = re.search(r\\\"\\\\[\\\\[(\\\\d+(?:\\\\.\\\\d+)?)\\\\]\\\\]\\\", raw)\\n    if not match:\\n        return None\\n    score = float(match.group(1))\\n    if 1 <= score <= 10:\\n        return score\\n    return None\\n\\n\\nclass JudgeInterface(ABC):\\n    \\\"\\\"\\\"Base class for all LLM judges.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    def evaluate(self, prompt: str, response_a: str, response_b: str,\\n                 swap_position: bool = False) -> dict:\\n        \\\"\\\"\\\"Pairwise evaluation.\\n\\n        Returns:\\n            {score: float|None, raw_output: str, position: \\\"AB\\\"|\\\"BA\\\"}\\n            score: 1.0=A wins, 0.0=B wins, 0.5=tie, None=parse failure\\n        \\\"\\\"\\\"\\n        pass\\n\\n    @abstractmethod\\n    def evaluate_pointwise(self, prompt: str, response: str) -> dict:\\n        \\\"\\\"\\\"Pointwise evaluation (1-10 scale).\\n\\n        Returns:\\n            {score: float|None (1-10), raw_output: str}\\n        \\\"\\\"\\\"\\n        pass\\n\\n    def _build_prompt(self, prompt: str, response_a: str, response_b: str,\\n                      swap_position: bool) -> tuple[str, str]:\\n        if swap_position:\\n            text = PAIRWISE_JUDGE_PROMPT.format(\\n                prompt=prompt, response_a=response_b, response_b=response_a)\\n            return text, \\\"BA\\\"\\n        else:\\n            text = PAIRWISE_JUDGE_PROMPT.format(\\n                \\n\\n... [截断: 输出过长，省略 3985 字符] ..